#include <torch/extension.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

#define FULL_MASK 0xffffffffu

__global__ void ln_kernel(const float4* __restrict__ x4,
                          const float4* __restrict__ w4,
                          const float4* __restrict__ b4,
                          float4* __restrict__ y4,
                          float* __restrict__ g_sum,
                          float* __restrict__ g_sumsq,
                          float* __restrict__ g_mean,
                          float* __restrict__ g_rstd,
                          unsigned int* __restrict__ counters,
                          unsigned int* __restrict__ flags,
                          int n4, int chunks, float eps) {
    int row = blockIdx.y;
    int chunk = blockIdx.x;
    int chunk_size = (n4 + chunks - 1) / chunks;
    int start = chunk * chunk_size;
    int end = min(start + chunk_size, n4);
    const float4* xr = x4 + (long)row * (long)n4;
    float s = 0.f, sq = 0.f;
    for (int i = start + threadIdx.x; i < end; i += blockDim.x) {
        float4 v = xr[i];
        s += v.x + v.y + v.z + v.w;
        sq += v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
