    __shared__ float sh_s[32];
    __shared__ float sh_q[32];
    for (int off = 16; off > 0; off >>= 1) {
        s += __shfl_down_sync(FULL_MASK, s, off);
        sq += __shfl_down_sync(FULL_MASK, sq, off);
    }
    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
    if (lane == 0) { sh_s[warp] = s; sh_q[warp] = sq; }
    __syncthreads();
    int nwarp = (blockDim.x + 31) >> 5;
    if (warp == 0) {
        s = (lane < nwarp) ? sh_s[lane] : 0.f;
        sq = (lane < nwarp) ? sh_q[lane] : 0.f;
        for (int off = 16; off > 0; off >>= 1) {
            s += __shfl_down_sync(FULL_MASK, s, off);
            sq += __shfl_down_sync(FULL_MASK, sq, off);
        }
        if (lane == 0) {
            atomicAdd(&g_sum[row], s);
            atomicAdd(&g_sumsq[row], sq);
            __threadfence();
            unsigned int done = atomicAdd(&counters[row], 1u);
            if (done == (unsigned int)(chunks - 1)) {
                float n = (float)n4 * 4.0f;
                float mean = g_sum[row] / n;
                float var = g_sumsq[row] / n - mean * mean;
                float rstd = rsqrtf(var + eps);
                g_mean[row] = mean;
                g_rstd[row] = rstd;
                __threadfence();
                atomicExch(&flags[row], 1u);
            }
        }
    }
    __shared__ float s_mean, s_rstd;
    if (threadIdx.x == 0) {
