        while (vf[row] == 0u) { __nanosleep(64); }
        __threadfence();
        s_mean = g_mean[row];
        s_rstd = g_rstd[row];
    }
    __syncthreads();
    float mean = s_mean;
    float rstd = s_rstd;
    float4* yr = y4 + (long)row * (long)n4;
    for (int i = start + threadIdx.x; i < end; i += blockDim.x) {
        float4 v = xr[i];
        float4 wv = w4[i];
        float4 bv = b4[i];
        float4 o;
        o.x = (v.x - mean) * rstd * wv.x + bv.x;
        o.y = (v.y - mean) * rstd * wv.y + bv.y;
        o.z = (v.z - mean) * rstd * wv.z + bv.z;
        o.w = (v.w - mean) * rstd * wv.w + bv.w;
        yr[i] = o;
    }
}

torch::Tensor ln_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b,
                         torch::Tensor ws, double eps, int64_t chunks_req) {
    auto y = torch::empty_like(x);
    int64_t M = x.size(0);
    int64_t N = x.numel() / M;
    int n4 = (int)(N / 4);
    float* fws = (float*)ws.data_ptr<int>();
    unsigned int* iws = (unsigned int*)ws.data_ptr<int>();
    float* g_sum = fws;
    float* g_sumsq = fws + M;
    float* g_mean = fws + 2*M;
    float* g_rstd = fws + 3*M;
    unsigned int* counters = iws + 4*M;
    unsigned int* flags = iws + 5*M;

    int dev; cudaGetDevice(&dev);
    int numSMs; cudaDeviceGetAttribute(&numSMs, cudaDevAttrMultiProcessorCount, dev);
    int blocksPerSM = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocksPerSM, (const void*)ln_kernel, 256, 0);
    int64_t maxResident = (int64_t)numSMs * std::max(blocksPerSM, 1);
    int64_t chunks = chunks_req;
    if (chunks * M > maxResident) chunks = std::max<int64_t>(1, maxResident / M);

    dim3 grid((unsigned)chunks, (unsigned)M);
    auto stream = at::cuda::getCurrentCUDAStream();
    ln_kernel<<<grid, 256, 0, stream>>>(
        (const float4*)x.data_ptr<float>(),
        (const float4*)w.data_ptr<float>(),
        (const float4*)b.data_ptr<float>(),
        (float4*)y.data_ptr<float>(),
        g_sum, g_sumsq, g_mean, g_rstd, counters, flags,
        n4, (int)chunks, (float)eps);
    return y;
}
'''

