        ms = triton.testing.do_bench(lambda: cuda_fn(x, w, b, eps, ws, chunks), warmup=10, rep=50)
        print(f'chunks={chunks}: diff={diff:.3e} ok={ok} time={ms:.4f} ms')
    ms_native = triton.testing.do_bench(lambda: ln(x), warmup=10, rep=50)
    print(f'native: {ms_native:.4f} ms')

if __name__ == '__main__':
    main()
